  1→import { Link } from '@inertiajs/react';
  2→import { ChevronRight, Leaf } from 'lucide-react';
  3→import { show as subExploitationShow } from '@/actions/App/Http/Controllers/SubExploitationController';
  4→
  5→type SubExploitationCardProps = {
  6→    id: number;
  7→    species: string;
  8→    exploitationType: string;
  9→    zootechnicalClassification: string;
 10→    productiveSystem: string;
 11→    currentCapacity: number;
 12→    maxCapacity: number;
 13→    sustainability: string | null;
 14→    selfConsumption: boolean;
 15→    animalsCount: number;
 16→};
 17→
 18→const speciesLabels: Record<string, string> = {
 19→    bovine: 'Bovino',
 20→    ovine: 'Ovino',
 21→    caprine: 'Caprino',
 22→    porcine: 'Porcino',
 23→    equine: 'Equino',
 24→};
 25→
 26→const speciesHeaderColors: Record<string, string> = {
 27→    bovine: 'bg-[#E53935]',
 28→    ovine: 'bg-black',
 29→    caprine: 'bg-black',
 30→    porcine: 'bg-neutral-700',
 31→    equine: 'bg-amber-900',
 32→};
 33→
 34→function getCapacityColor(current: number, max: number): string {
 35→    const ratio = max > 0 ? current / max : 0;
 36→    if (ratio > 0.8) return 'bg-[#E53935]';
 37→    if (ratio > 0.6) return 'bg-amber-500';
 38→    return 'bg-[#2E7D32]';
 39→}
 40→
 41→function getSustainabilityStyle(sustainability: string | null): { bg: string; text: string; hasIcon: boolean } {
 42→    switch (sustainability?.toLowerCase()) {
 43→        case 'ecológico':
 44→            return { bg: 'bg-[#2E7D32] text-white', text: 'Ecológico', hasIcon: true };
 45→        case 'integrado':
 46→            return { bg: 'bg-[#F9A825] text-black', text: 'Integrado', hasIcon: false };
 47→        default:
 48→            return { bg: 'bg-neutral-200 text-neutral-600', text: sustainability ?? 'Convencional', hasIcon: false };
 49→    }
 50→}
 51→
 52→export function SubExploitationCard({
 53→    id,
 54→    species,
 55→    exploitationType,
 56→    zootechnicalClassification,
 57→    productiveSystem,
 58→    currentCapacity,
 59→    maxCapacity,
 60→    sustainability,
 61→    selfConsumption,
 62→    animalsCount,
 63→}: SubExploitationCardProps) {
 64→    const label = speciesLabels[species] ?? species;
 65→    const headerColor = speciesHeaderColors[species] ?? 'bg-black';
 66→    const capacityColor = getCapacityColor(currentCapacity, maxCapacity);
 67→    const capacityPercent = maxCapacity > 0 ? Math.min((currentCapacity / maxCapacity) * 100, 100) : 0;
 68→    const sustainabilityStyle = getSustainabilityStyle(sustainability);
 69→
 70→    return (
 71→        <div className="overflow-hidden rounded-lg border-2 border-black">
 72→            {/* Header */}
 73→            <div className={`${headerColor} px-4 py-3.5 text-white`}>
 74→                <p className="text-[15px] font-bold">
 75→                    {label} · {zootechnicalClassification}
 76→                </p>
 77→                <p className="text-xs font-medium opacity-80">{exploitationType}</p>
 78→            </div>
 79→
 80→            {/* Body */}
 81→            <div className="flex flex-col gap-3 p-4">
 82→                {/* Sistema productivo */}
 83→                <div className="flex items-center justify-between">
 84→                    <span className="text-[13px] font-medium text-neutral-500">Sistema productivo</span>
 85→                    <span className="text-[13px] font-bold">{productiveSystem}</span>
 86→                </div>
 87→
 88→                {/* Capacidad */}
 89→                <div className="flex flex-col gap-1.5">
 90→                    <div className="flex items-center justify-between">
 91→                        <span className="text-[13px] font-medium text-neutral-500">Capacidad</span>
 92→                        <span className="text-[13px] font-bold">
 93→                            {currentCapacity} / {maxCapacity}
 94→                        </span>
 95→                    </div>
 96→                    <div className="h-2 w-full rounded-sm bg-neutral-100">
 97→                        <div
 98→                            className={`h-2 rounded-sm ${capacityColor}`}
 99→                            style={{ width: `${capacityPercent}%` }}
100→                        />
101→                    </div>
102→                </div>
103→
104→                {/* Badges */}
105→                <div className="flex flex-wrap gap-2">
106→                    {sustainability && (
107→                        <span
108→                            className={`inline-flex items-center gap-1 rounded-sm px-2.5 py-1 text-[11px] font-bold ${sustainabilityStyle.bg}`}
109→                        >
110→                            {sustainabilityStyle.hasIcon && <Leaf className="size-3" />}
111→                            {sustainabilityStyle.text}
112→                        </span>
113→                    )}
114→                    <span className="inline-flex items-center rounded-sm border border-neutral-300 px-2.5 py-1 text-[11px] font-semibold text-neutral-500">
115→                        Autoconsumo: {selfConsumption ? 'SÍ' : 'NO'}
116→                    </span>
117→                </div>
118→
119→                {/* Divider */}
120→                <div className="h-px w-full bg-neutral-100" />
121→
122→                {/* Footer */}
123→                <div className="flex items-center justify-between">
124→                    <span className="text-[13px] font-semibold">Censo: {animalsCount} animales</span>
125→                    <Link href={subExploitationShow.url(id)} className="flex items-center gap-1 text-[13px] font-semibold text-[#E53935]">
126→                        Ver detalle
127→                        <ChevronRight className="size-4" />
128→                    </Link>
129→                </div>
130→            </div>
131→        </div>
132→    );
133→}
