 1→import { Beef } from 'lucide-react';
 2→
 3→type SpeciesFilterProps = {
 4→    species: string[];
 5→    activeSpecies: string | null;
 6→    onSelect: (species: string | null) => void;
 7→};
 8→
 9→const speciesLabels: Record<string, string> = {
10→    bovine: 'Bovino',
11→    ovine: 'Ovino',
12→    caprine: 'Caprino',
13→    porcine: 'Porcino',
14→    equine: 'Equino',
