17→export function SpeciesFilter({ species, activeSpecies, onSelect }: SpeciesFilterProps) {
18→    return (
19→        <div className="flex gap-2 overflow-x-auto">
20→            <button
21→                onClick={() => onSelect(null)}
22→                className={`flex shrink-0 items-center gap-1.5 rounded-full px-3.5 py-2 text-xs font-semibold transition-colors ${
23→                    activeSpecies === null
24→                        ? 'bg-[#E53935] text-white'
25→                        : 'border-2 border-black bg-white text-black'
26→                }`}
27→            >
28→                Todos
29→            </button>
30→            {species.map((s) => (
31→                <button
32→                    key={s}
33→                    onClick={() => onSelect(s)}
34→                    className={`flex shrink-0 items-center gap-1.5 rounded-full px-3.5 py-2 text-xs font-semibold transition-colors ${
35→                        activeSpecies === s
36→                            ? 'bg-[#E53935] text-white'
37→                            : 'border-2 border-black bg-white text-black'
38→                    }`}
39→                >
40→                    {activeSpecies === s && s === 'bovine' && <Beef className="size-4" />}
41→                    {speciesLabels[s] ?? s}
42→                </button>
43→            ))}
44→        </div>
45→    );
46→}
