        href: '/scanner',
        icon: Camera,
    },
    {
        title: 'Comunicar Nacimiento',
        href: '/nacimientos/crear',
        icon: Baby,
    },
    {
        title: 'Normativa',
        href: '/normativa',
        icon: Bell,
    },
    {
        title: 'NekazarIA Chat',
        href: '/chat',
        icon: MessageCircle,
    },
];

export function AppSidebar() {
    return (
        <Sidebar collapsible="icon" variant="inset">
            <SidebarHeader>
                <SidebarMenu>
                    <SidebarMenuItem>
                        <SidebarMenuButton size="lg" asChild>
                            <Link href={dashboard()} prefetch>
                                <AppLogo />
                            </Link>
                        </SidebarMenuButton>
                    </SidebarMenuItem>
                </SidebarMenu>
            </SidebarHeader>

            <SidebarContent>
                <NavMain items={mainNavItems} />
